{"path":"/workspace/backend/internal/db/db.go","command":"create","file_text":"package db

import (
	"context"
	"fmt"
	"os"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
	"go.mongodb.org/mongo-driver/mongo/readpref"
)

type DB struct {
	PG    *pgxpool.Pool
	Mongo *mongo.Client
	MongoDB *mongo.Database
}

func Connect(ctx context.Context) (*DB, error) {
	pgURL := os.Getenv("DATABASE_URL")
	if pgURL == "" {
		pgURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	cfg, err := pgxpool.ParseConfig(pgURL)
	if err != nil {
		return nil, fmt.Errorf("parse pg: %w", err)
	}
	cfg.MaxConns = 20
	pg, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("connect pg: %w", err)
	}
	if err := pg.Ping(ctx); err != nil {
		return nil, fmt.Errorf("ping pg: %w", err)
	}

	mongoURI := os.Getenv("MONGODB_URI")
	if mongoURI == "" {
		mongoURI = "mongodb://127.0.0.1:27017/arena"
	}
	mctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	mc, err := mongo.Connect(mctx, options.Client().ApplyURI(mongoURI))
	if err != nil {
		pg.Close()
		return nil, fmt.Errorf("connect mongo: %w", err)
	}
	if err := mc.Ping(mctx, readpref.Primary()); err != nil {
		pg.Close()
		_ = mc.Disconnect(ctx)
		return nil, fmt.Errorf("ping mongo: %w", err)
	}

	return &DB{PG: pg, Mongo: mc, MongoDB: mc.Database("arena")}, nil
}

func (d *DB) Close() {
	if d.PG != nil {
		d.PG.Close()
	}
	if d.Mongo != nil {
		_ = d.Mongo.Disconnect(context.Background())
	}
}

func (d *DB) Ready(ctx context.Context) error {
	if err := d.PG.Ping(ctx); err != nil {
		return err
	}
	mctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()
	return d.Mongo.Ping(mctx, readpref.Primary())
}
"}

{"path":"/workspace/backend/internal/auth/auth.go","command":"create","file_text":"package auth

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"time"

	"labpd/internal/db"
	"labpd/internal/models"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"golang.org/x/crypto/bcrypt"
)

var (
	ErrInvalidCredentials = errors.New("invalid_credentials")
	ErrUnauthorized       = errors.New("unauthorized")
)

type Session struct {
	Token      string
	UserID     uuid.UUID
	ActiveRole string
	User       *models.User
}

type Service struct {
	db *db.DB
}

func New(database *db.DB) *Service {
	return &Service{db: database}
}

func HashPassword(pw string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	return string(b), err
}

func CheckPassword(hash, pw string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

func newToken() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func (s *Service) Authenticate(ctx context.Context, username, password string) (*Session, error) {
	u, err := s.getUserByUsername(ctx, username)
	if err != nil {
		return nil, ErrInvalidCredentials
	}
	if !u.Active || !CheckPassword(u.PasswordHash, password) {
		return nil, ErrInvalidCredentials
	}
	token, err := newToken()
	if err != nil {
		return nil, err
	}
	activeRole := ""
	if len(u.Roles) == 1 {
		activeRole = u.Roles[0]
	}
	_, err = s.db.PG.Exec(ctx,
		`INSERT INTO sessions (token, user_id, active_role, expires_at) VALUES ($1,$2,$3,$4)`,
		token, u.ID, activeRole, time.Now().Add(24*time.Hour))
	if err != nil {
		return nil, err
	}
	return &Session{Token: token, UserID: u.ID, ActiveRole: activeRole, User: u}, nil
}

func (s *Service) GetSession(ctx context.Context, token string) (*Session, error) {
	if token == "" {
		return nil, ErrUnauthorized
	}
	var sess Session
	var userID uuid.UUID
	var activeRole string
	err := s.db.PG.QueryRow(ctx,
		`SELECT token, user_id, active_role FROM sessions WHERE token=$1 AND expires_at > NOW()`,
		token).Scan(&sess.Token, &userID, &activeRole)
	if err != nil {
		return nil, ErrUnauthorized
	}
	u, err := s.GetUser(ctx, userID)
	if err != nil || !u.Active {
		return nil, ErrUnauthorized
	}
	sess.UserID = userID
	sess.ActiveRole = activeRole
	sess.User = u
	return &sess, nil
}

func (s *Service) SelectRole(ctx context.Context, token, role string) error {
	_, err := s.db.PG.Exec(ctx, `UPDATE sessions SET active_role=$1 WHERE token=$2`, role, token)
	return err
}

func (s *Service) DeleteSession(ctx context.Context, token string) error {
	_, err := s.db.PG.Exec(ctx, `DELETE FROM sessions WHERE token=$1`, token)
	return err
}

func (s *Service) GetUser(ctx context.Context, id uuid.UUID) (*models.User, error) {
	row := s.db.PG.QueryRow(ctx, `
		SELECT id, username, password_hash, email, full_name, phone, roles, qualifications,
		       certifications, active, assigned_location_id, available, capacity_units,
		       decline_count, decline_penalty_until, latest_lat, latest_lng, location_recorded_at
		FROM users WHERE id=$1`, id)
	return scanUser(row)
}

func (s *Service) getUserByUsername(ctx context.Context, username string) (*models.User, error) {
	row := s.db.PG.QueryRow(ctx, `
		SELECT id, username, password_hash, email, full_name, phone, roles, qualifications,
		       certifications, active, assigned_location_id, available, capacity_units,
		       decline_count, decline_penalty_until, latest_lat, latest_lng, location_recorded_at
		FROM users WHERE username=$1`, username)
	return scanUser(row)
}

func scanUser(row pgx.Row) (*models.User, error) {
	var u models.User
	var certs []byte
	err := row.Scan(
		&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		&u.Roles, &u.Qualifications, &certs, &u.Active, &u.AssignedLocationID,
		&u.Available, &u.CapacityUnits, &u.DeclineCount, &u.DeclinePenaltyUntil,
		&u.LatestLat, &u.LatestLng, &u.LocationRecordedAt,
	)
	if err != nil {
		return nil, err
	}
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	u.Certifications = parseCerts(certs)
	return &u, nil
}

func parseCerts(b []byte) []models.Certification {
	if len(b) == 0 || string(b) == "null" {
		return []models.Certification{}
	}
	// simple JSON unmarshal via encoding/json in caller; keep flexible
	var out []models.Certification
	_ = jsonUnmarshal(b, &out)
	if out == nil {
		out = []models.Certification{}
	}
	return out
}

// avoid import cycle helpers
func jsonUnmarshal(b []byte, v interface{}) error {
	return jsonUnmarshalImpl(b, v)
}
"}

