		{"Pulse", "Pulse", "standard", 2, 25, false, false},
	}
	var ids = map[string]uuid.UUID{}
	for _, d := range defaults {
		var id uuid.UUID
		err := s.DB.PG.QueryRow(ctx, `SELECT id FROM sample_types WHERE name=$1`, d.name).Scan(&id)
		if err == pgx.ErrNoRows {
