func (s *Service) GetIdempotent(ctx context.Context, key, endpoint, reqHash string) (status int, body []byte, conflict bool, found bool) {
	if key == "" {
		return 0, nil, false, false
	}
	var st int
	var bh string
	var rb []byte
	err := s.DB.PG.QueryRow(ctx, `SELECT request_hash, response_status, response_body FROM idempotency_keys WHERE key=$1 AND endpoint=$2`, key, endpoint).
		Scan(&bh, &st, &rb)
	if err == pgx.ErrNoRows {
		return 0, nil, false, false
	}
	if err != nil {
