			"transfer_point":   loc.Functions.TransferPoint,
			"hub":              loc.Functions.Hub,
			"laboratory":       loc.Functions.Laboratory,
		},
	}, nil
}

func (s *Service) listLocations(ctx context.Context) ([]models.Location, error) {
	rows, err := s.DB.PG.Query(ctx, `
