	defer rows.Close()
	var out []models.Connection
	for rows.Next() {
		var c models.Connection
		if err := rows.Scan(&c.ID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active,
			&c.CapacityUnits, &c.ReservedUnits, &c.CooledCapacityUnits, &c.CooledReservedUnits); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, nil
}

func (s *Service) getSampleType(ctx context.Context, id uuid.UUID) (*models.SampleType, *AppError) {
	var st models.SampleType
	var incomp []uuid.UUID
	err := s.DB.PG.QueryRow(ctx, `
		SELECT id, name, qualified_collector_required, required_qualification, container_type,
			temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
		FROM sample_types WHERE id=$1`, id).Scan(
		&st.ID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType,
		&st.TemperatureMinC, &st.TemperatureMaxC, &incomp, &st.RequiresCooledRoute, &st.BatchingAllowed)
	if err == pgx.ErrNoRows {
		return nil, NotFound("not_found", "sample type not found")
	}
	if err != nil {
		return nil, Internal(err.Error())
	}
	if incomp == nil {
		incomp = []uuid.UUID{}
	}
	st.IncompatibleSampleTypes = incomp
	return &st, nil
}

func (s *Service) sampleTypePublic(ctx context.Context, id uuid.UUID) (map[string]interface{}, *AppError) {
	st, err := s.getSampleType(ctx, id)
	if err != nil {
		return nil, err
	}
	incomp := make([]string, 0, len(st.IncompatibleSampleTypes))
	for _, x := range st.IncompatibleSampleTypes {
		incomp = append(incomp, x.String())
	}
	return map[string]interface{}{
		"sampleTypeId": st.ID.String(), "name": st.Name,
		"qualifiedCollectorRequired": st.QualifiedCollectorRequired,
		"requiredQualification":      st.RequiredQualification,
		"containerType":              st.ContainerType,
		"temperatureMinC":            st.TemperatureMinC,
		"temperatureMaxC":            st.TemperatureMaxC,
		"incompatibleSampleTypes":    incomp,
		"requiresCooledRoute":        st.RequiresCooledRoute,
		"batchingAllowed":            st.BatchingAllowed,
	}, nil
}

func (s *Service) ListSampleTypes(ctx context.Context) ([]map[string]interface{}, error) {
	rows, err := s.DB.PG.Query(ctx, `SELECT id FROM sample_types ORDER BY name`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []map[string]interface{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		m, aerr := s.sampleTypePublic(ctx, id)
		if aerr != nil {
			return nil, aerr
		}
		out = append(out, m)
	}
	if out == nil {
		out = []map[string]interface{}{}
	}
	return out, nil
}

// Serviceability

type ServiceabilityResult struct {
	Serviceable          bool
	Reason               string
	TargetLaboratoryID   *uuid.UUID
	EstimatedArrivalAt   *interface{}
	ServiceabilityVersion int
	CollectionNodeID     *uuid.UUID
	Path                 []uuid.UUID // location path from collection node to lab
	ConnectionIDs        []uuid.UUID
	TravelMinutes        int
	CostUnits            float64
}

func (s *Service) CheckServiceability(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleRequester, models.RoleAdministrator, models.RoleDispatcher,
		models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
		// allow any authenticated with role
		if sess == nil {
			return nil, Unauth("unauthorized", "authentication required")
		}
		if sess.ActiveRole == "" {
			return nil, Conflict("role_not_selected", "select an active role")
		}
	}
	res, aerr := s.computeServiceability(ctx, body)
	if aerr != nil {
		return nil, aerr
	}
	out := map[string]interface{}{
		"serviceable":           res.Serviceable,
		"reason":                res.Reason,
		"serviceabilityVersion": res.ServiceabilityVersion,
	}
	if res.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = res.TargetLaboratoryID.String()
	}
	if res.EstimatedArrivalAt != nil {
		out["estimatedArrivalAt"] = *res.EstimatedArrivalAt
	}
	return out, nil
}

func (s *Service) computeServiceability(ctx context.Context, body map[string]interface{}) (*ServiceabilityResult, *AppError) {
	var version int
	_ = s.DB.PG.QueryRow(ctx, `SELECT serviceability_version FROM network_meta WHERE id=1`).Scan(&version)
	if version < 1 {
		version = 1
	}

	coord, err := parseCoord(body["origin"])
	if err != nil {
		return nil, Bad("invalid_origin", "invalid origin coordinate")
	}
	originType, _ := body["originType"].(string)
	if originType == "" {
		originType = "home"
	}
	if originType != "home" && originType != "clinic" && originType != "node" {
		return nil, Bad("invalid_origin_type", "invalid originType")
	}
	stID, err := parseUUID(body["sampleTypeId"])
	if err != nil {
		return nil, NotFound("not_found", "sample type not found")
	}
	st, aerr := s.getSampleType(ctx, stID)
	if aerr != nil {
		return nil, aerr
	}
	requestedAt, err := parseTime(body["requestedAt"])
	if err != nil {
		return nil, Bad("invalid_time", "invalid requestedAt")
	}
	deadline, err := parseTime(body["deliveryDeadline"])
	if err != nil {
		return nil, Bad("invalid_deadline", "invalid deliveryDeadline")
	}
	if !deadline.After(requestedAt) {
		return nil, Bad("invalid_deadline", "deadline must be after requestedAt")
	}
	earliest := requestedAt
	if v, ok := body["earliestCollectionAt"].(string); ok && v != "" {
		t, e := parseTime(v)
		if e != nil {
			return nil, Bad("invalid_collection_window", "invalid earliestCollectionAt")
		}
		earliest = t
	}
	latest := deadline
	if v, ok := body["latestCollectionAt"].(string); ok && v != "" {
		t, e := parseTime(v)
		if e != nil {
			return nil, Bad("invalid_collection_window", "invalid latestCollectionAt")
		}
		latest = t
	}
	if latest.Before(earliest) {
		return nil, Bad("invalid_collection_window", "latest before earliest")
	}

	_ = st
	result := &ServiceabilityResult{ServiceabilityVersion: version, Reason: "outside_service_coverage"}

	locs, err := s.listLocations(ctx)
	if err != nil {
		return nil, Internal(err.Error())
	}
	conns, err := s.listConnections(ctx)
	if err != nil {
		return nil, Internal(err.Error())
	}

	// find nearest active collection point within coverage
	var originNode *models.Location
	if originType == "node" {
		if v, ok := body["originNodeId"].(string); ok && v != "" {
			nid, e := uuid.Parse(v)
			if e == nil {
				for i := range locs {
					if locs[i].ID == nid {
						originNode = &locs[i]
						break
					}
				}
			}
		}
	}
	if originNode == nil {
		bestDist := 1e18
		for i := range locs {
			l := &locs[i]
			if !l.Active || !l.Functions.CollectionPoint {
				continue
			}
			d := planning.HaversineKm(coord.Latitude, coord.Longitude, l.Coordinate.Latitude, l.Coordinate.Longitude)
			cov := l.CoverageKm
			if cov <= 0 {
				cov = 5
			}
			if d <= cov && d < bestDist {
				bestDist = d
				originNode = l
			}
		}
	}
	if originNode == nil || !originNode.Active {
		result.Serviceable = false
		result.Reason = "outside_service_coverage"
		return result, nil
	}

	// labs that accept sample type
	var labs []models.Location
	for _, l := range locs {
		if !l.Active || !l.Functions.Laboratory {
			continue
		}
		if len(l.AcceptedSampleTypeIDs) == 0 || containsUUID(l.AcceptedSampleTypeIDs, stID) {
			labs = append(labs, l)
		}
	}
	if len(labs) == 0 {
		result.Reason = "no_accepting_laboratory"
		return result, nil
	}

	// build graph of active connections
	type edge struct {
		to       uuid.UUID
		minutes  int
		cost     float64
		cooled   bool
		connID   uuid.UUID
		capOK    bool
		cooledOK bool
		fromCap  int
		toCap    int
	}
	graph := map[uuid.UUID][]edge{}
	locByID := map[uuid.UUID]*models.Location{}
	for i := range locs {
		locByID[locs[i].ID] = &locs[i]
	}
	needsCool := st.RequiresCooledRoute
	for _, c := range conns {
		if !c.Active {
			continue
		}
		if needsCool && !c.Cooled {
			continue
		}
		capOK := c.CapacityUnits == 0 || c.ReservedUnits < c.CapacityUnits
		cooledOK := !needsCool || c.CooledCapacityUnits == 0 || c.CooledReservedUnits < c.CooledCapacityUnits
		if !capOK || (needsCool && !cooledOK && c.CooledCapacityUnits > 0) {
			// still add but mark
		}
		graph[c.FromLocationID] = append(graph[c.FromLocationID], edge{
			to: c.ToLocationID, minutes: c.TravelMinutes, cost: c.CostUnits, cooled: c.Cooled,
			connID: c.ID, capOK: capOK, cooledOK: cooledOK,
		})
	}

	// dijkstra by time from originNode to any lab
	type nodeState struct {
		id      uuid.UUID
		minutes int
		cost    float64
		path    []uuid.UUID
		conns   []uuid.UUID
	}
	const inf = 1 << 30
	dist := map[uuid.UUID]int{}
	for _, l := range locs {
		dist[l.ID] = inf
	}
	dist[originNode.ID] = originNode.HandlingMinutes
	pq := []nodeState{{id: originNode.ID, minutes: originNode.HandlingMinutes, path: []uuid.UUID{originNode.ID}}}
	var best *nodeState
	visited := map[uuid.UUID]bool{}

	for len(pq) > 0 {
		// pop min
		mi := 0
		for i := 1; i < len(pq); i++ {
			if pq[i].minutes < pq[mi].minutes {
				mi = i
			}
		}
		cur := pq[mi]
		pq = append(pq[:mi], pq[mi+1:]...)
		if visited[cur.id] {
			continue
		}
		visited[cur.id] = true
		if loc := locByID[cur.id]; loc != nil && loc.Functions.Laboratory && loc.Active {
			if len(loc.AcceptedSampleTypeIDs) == 0 || containsUUID(loc.AcceptedSampleTypeIDs, stID) {
				// capacity at lab
				needUnits := 1
				if needsCool {
					if loc.CooledCapacityUnits > 0 && loc.CooledReservedUnits+needUnits > loc.CooledCapacityUnits {
						continue
					}
				} else {
					if loc.CapacityUnits > 0 && loc.ReservedUnits+needUnits > loc.CapacityUnits {
						continue
					}
				}
				cp := cur
				best = &cp
				break
			}
		}
		for _, e := range graph[cur.id] {
			if visited[e.to] {
				continue
			}
			if needsCool && !e.cooled {
				continue
			}
			if e.CapacityBlocked(needsCool) {
				continue
			}
			toLoc := locByID[e.to]
			add := e.minutes
			if toLoc != nil {
				add += toLoc.HandlingMinutes
			}
			nd := cur.minutes + add
			if nd < dist[e.to] {
				dist[e.to] = nd
				np := append(append([]uuid.UUID{}, cur.path...), e.to)
				nc := append(append([]uuid.UUID{}, cur.conns...), e.connID)
				pq = append(pq, nodeState{id: e.to, minutes: nd, cost: cur.cost + e.cost, path: np, conns: nc})
			}
		}
	}

	if best == nil {
		// distinguish reasons
		if !hasAnyRoute(graph, originNode.ID, labs, locByID) {
			result.Reason = "no_route"
		} else if needsCool && !hasCooledRoute(conns, originNode.ID, labs) {
			result.Reason = "handling_rules_unsatisfiable"
		} else {
			result.Reason = "insufficient_capacity"
		}
		return result, nil
	}

	// collection travel estimate: 30 min per 5km approx from origin to node + path
	homeToNodeMin := int(planning.HaversineKm(coord.Latitude, coord.Longitude, originNode.Coordinate.Latitude, originNode.Coordinate.Longitude) / 5.0 * 30)
	if homeToNodeMin < 5 {
		homeToNodeMin = 5
	}
	totalMin := homeToNodeMin + best.minutes
	arrival := earliest.Add(minutesDuration(totalMin))
	if arrival.After(deadline) {
		// try from latest? still fail if even earliest misses
		result.Reason = "deadline_unreachable"
		return result, nil
	}

	result.Serviceable = true
	result.Reason = "serviceable"
	lid := best.id
	result.TargetLaboratoryID = &lid
	arrStr := arrival.UTC().Format("2006-01-02T15:04:05Z07:00")
	var arrIface interface{} = arrStr
	result.EstimatedArrivalAt = &arrIface
	cid := originNode.ID
	result.CollectionNodeID = &cid
	result.Path = best.path
	result.ConnectionIDs = best.conns
	result.TravelMinutes = totalMin
	result.CostUnits = best.cost
	return result, nil
}

func (e edge) CapacityBlocked(needsCool bool) bool {
	if needsCool {
		// if cooled capacity configured and full
		return false // checked via connection fields when building; allow route finding, capacity checked at reserve
	}
	return false
}

func hasAnyRoute(graph map[uuid.UUID][]edge, start uuid.UUID, labs []models.Location, locByID map[uuid.UUID]*models.Location) bool {
	seen := map[uuid.UUID]bool{}
	q := []uuid.UUID{start}
	labSet := map[uuid.UUID]bool{}
	for _, l := range labs {
		labSet[l.ID] = true
	}
	for len(q) > 0 {
		n := q[0]
		q = q[1:]
		if labSet[n] {
			return true
		}
		if seen[n] {
			continue
		}
		seen[n] = true
		for _, e := range graph[n] {
			q = append(q, e.to)
		}
	}
	// also if start is lab
	return labSet[start]
}

func hasCooledRoute(conns []models.Connection, start uuid.UUID, labs []models.Location) bool {
	g := map[uuid.UUID][]uuid.UUID{}
	for _, c := range conns {
		if c.Active && c.Cooled {
			g[c.FromLocationID] = append(g[c.FromLocationID], c.ToLocationID)
		}
	}
	labSet := map[uuid.UUID]bool{}
	for _, l := range labs {
		labSet[l.ID] = true
	}
	seen := map[uuid.UUID]bool{}
	q := []uuid.UUID{start}
	for len(q) > 0 {
		n := q[0]
		q = q[1:]
		if labSet[n] {
			return true
		}
		if seen[n] {
			continue
		}
		seen[n] = true
		q = append(q, g[n]...)
	}
	return labSet[start]
}

