func (s *Service) AcceptAssignment(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator, models.RoleDispatcher); err != nil {
		return nil, err
	}
	idem, _ := body["idempotencyKey"].(string)
	if idem == "" {
		return nil, Bad("idempotency_required", "idempotencyKey required")
	}
	aID, err := parseUUID(body["assignmentId"])
	if err != nil {
		return nil, Bad("invalid_json", "invalid assignmentId")
	}
	reqHash := hashReq(body)
	if st, rb, conflict, found := s.GetIdempotent(ctx, idem, "accept_assignment", reqHash); found {
		if conflict {
			return nil, Conflict("idempotency_conflict", "conflict")
		}
		var out map[string]interface{}
		_ = jsonUnmarshal(rb, &out)
		return out, nil
	}

	var status string
	var offeredTo, workerID *uuid.UUID
	var sampleID uuid.UUID
	err = s.DB.PG.QueryRow(ctx, `SELECT status, offered_to, worker_id, sample_id, offer_expires_at FROM assignments WHERE id=$1`, aID).
		Scan(&status, &offeredTo, &workerID, &sampleID, new(*time.Time))
	// re-query properly
	var exp *time.Time
	err = s.DB.PG.QueryRow(ctx, `SELECT status, offered_to, worker_id, sample_id, offer_expires_at FROM assignments WHERE id=$1`, aID).
		Scan(&status, &offeredTo, &workerID, &sampleID, &exp)
	if err == pgx.ErrNoRows {
		return nil, NotFound("not_found", "assignment not found")
	}
	if err != nil {
		return nil, Internal(err.Error())
	}
	if status == "accepted" && workerID != nil && *workerID == sess.UserID {
		out := map[string]interface{}{"assignmentId": aID.String(), "workerId": sess.UserID.String(), "status": "accepted"}
		return out, nil
	}
	if status != "offered" && status != "pending" {
		return nil, Conflict("assignment_inactive", "assignment not active")
	}
	if status == "offered" {
		if offeredTo == nil || *offeredTo != sess.UserID {
			if sess.ActiveRole != models.RoleAdministrator && sess.ActiveRole != models.RoleDispatcher {
				return nil, Conflict("offer_not_offered", "not offered to you")
			}
		}
		if exp != nil && exp.Before(time.Now()) {
			return nil, Conflict("offer_not_available", "offer expired")
		}
	}
	if !sess.User.Available && sess.ActiveRole != models.RoleAdministrator {
		return nil, Conflict("worker_unavailable", "worker unavailable")
	}

	tag, err := s.DB.PG.Exec(ctx, `
		UPDATE assignments SET status='accepted', worker_id=$1, offered_to=NULL, updated_at=NOW()
		WHERE id=$2 AND status IN ('offered','pending')`, sess.UserID, aID)
	if err != nil {
		return nil, Internal(err.Error())
	}
	if tag.RowsAffected() == 0 {
		return nil, Conflict("assignment_taken", "already taken")
	}
	s.Timeline(ctx, "assignment_accepted", sess.UserID.String(), sess.ActiveRole, "assignment", aID.String(), true,
		map[string]interface{}{"sampleId": sampleID.String()}, &sampleID, nil, &aID)
	s.Audit(ctx, sess.UserID.String(), sess.ActiveRole, "accept_assignment", "assignment", aID.String(), true, nil)
	out := map[string]interface{}{"assignmentId": aID.String(), "workerId": sess.UserID.String(), "status": "accepted"}
	s.SaveIdempotent(ctx, idem, "accept_assignment", reqHash, &sess.UserID, 201, map[string]interface{}{"data": out})
	return out, nil
}

func (s *Service) DeclineAssignment(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
		return nil, err
	}
	idem, _ := body["idempotencyKey"].(string)
	if idem == "" {
		return nil, Bad("idempotency_required", "idempotencyKey required")
	}
	aID, err := parseUUID(body["assignmentId"])
	if err != nil {
		return nil, Bad("invalid_json", "invalid assignmentId")
	}
	var status string
	var offeredTo *uuid.UUID
	var sampleID uuid.UUID
	var kind string
	var nodeID, labID *uuid.UUID
	err = s.DB.PG.QueryRow(ctx, `SELECT status, offered_to, sample_id, kind, node_id, laboratory_id FROM assignments WHERE id=$1`, aID).
		Scan(&status, &offeredTo, &sampleID, &kind, &nodeID, &labID)
	if err == pgx.ErrNoRows {
		return nil, NotFound("not_found", "not found")
	}
	if err != nil {
		return nil, Internal(err.Error())
	}
	if status != "offered" || offeredTo == nil || *offeredTo != sess.UserID {
		return nil, Conflict("offer_not_available", "not your offer")
	}
	declinedAt := time.Now().UTC()
	if v, ok := body["declinedAt"].(string); ok && v != "" {
		if t, e := parseTime(v); e == nil {
			declinedAt = t
		}
	}
	_, _ = s.DB.PG.Exec(ctx, `
		UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL,
			declined_by = array_append(declined_by, $1), updated_at=NOW() WHERE id=$2`, sess.UserID, aID)
	_, _ = s.DB.PG.Exec(ctx, `
		UPDATE users SET decline_count = decline_count + 1,
			decline_penalty_until = CASE WHEN decline_count >= 2 THEN NOW() + INTERVAL '30 minutes' ELSE decline_penalty_until END
		WHERE id=$1`, sess.UserID)

	// reoffer
	st, _ := s.getSampleTypeBySample(ctx, sampleID)
	var loc *uuid.UUID
	if kind == "node" {
		loc = nodeID
	} else if kind == "laboratory" {
		loc = labID
	}
	var declined []uuid.UUID
	_ = s.DB.PG.QueryRow(ctx, `SELECT declined_by FROM assignments WHERE id=$1`, aID).Scan(&declined)
	_ = s.offerAssignmentTx(ctx, &txAdapter{s.DB.PG}, aID, kind, sampleID, st, loc, declined)

	var reoffered *uuid.UUID
	_ = s.DB.PG.QueryRow(ctx, `SELECT offered_to FROM assignments WHERE id=$1`, aID).Scan(&reoffered)

	out := map[string]interface{}{
		"assignmentId": aID.String(), "status": "pending",
		"declinedBy": sess.UserID.String(), "declinedAt": declinedAt.Format(time.RFC3339),
	}
	if reoffered != nil {
		out["reofferedTo"] = reoffered.String()
	}
	s.Timeline(ctx, "assignment_declined", sess.UserID.String(), sess.ActiveRole, "assignment", aID.String(), true, nil, &sampleID, nil, &aID)
