func (s *Service) CollectAndSeal(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleCollectionProfessional, models.RoleAdministrator); err != nil {
		return nil, err
	}
	idem, _ := body["idempotencyKey"].(string)
	if idem == "" {
		return nil, Bad("idempotency_required", "idempotencyKey required")
	}
	sampleID, err := parseUUID(body["sampleId"])
	if err != nil {
		return nil, Bad("invalid_json", "invalid sampleId")
	}
	aID, err := parseUUID(body["assignmentId"])
	if err != nil {
		return nil, Bad("invalid_json", "invalid assignmentId")
	}
	collectedAt, err := parseTime(body["collectedAt"])
	if err != nil {
		return nil, Bad("invalid_time", "invalid collectedAt")
	}
	container, _ := body["containerType"].(string)
	temp, ok := toFloat(body["observedTemperatureC"])
	if !ok {
		return nil, Bad("invalid_json", "temperature required")
	}

	var status, kind string
	var workerID *uuid.UUID
	var sid uuid.UUID
	err = s.DB.PG.QueryRow(ctx, `SELECT status, kind, worker_id, sample_id FROM assignments WHERE id=$1`, aID).
		Scan(&status, &kind, &workerID, &sid)
	if err == pgx.ErrNoRows {
		return nil, NotFound("not_found", "assignment not found")
	}
	if kind != "collection" || sid != sampleID {
		return nil, Conflict("invalid_assignment", "not a collection assignment for sample")
	}
	if status != "accepted" && status != "in_progress" {
		return nil, Conflict("assignment_inactive", "assignment not accepted")
	}
	if workerID == nil || *workerID != sess.UserID {
		if sess.ActiveRole != models.RoleAdministrator {
			return nil, Forbid("ineligible_worker", "not your assignment")
		}
	}

	var tmin, tmax float64
	var earliest, latest time.Time
	var sealed bool
	err = s.DB.PG.QueryRow(ctx, `SELECT temperature_min_c, temperature_max_c, earliest_collection_at, latest_collection_at, sealed FROM samples WHERE id=$1`, sampleID).
		Scan(&tmin, &tmax, &earliest, &latest, &sealed)
	if err != nil {
		return nil, NotFound("not_found", "sample not found")
	}
	if sealed {
		out := map[string]interface{}{
			"sampleId": sampleID.String(), "status": "sealed", "currentHolderId": sess.UserID.String(),
			"sealedAt": collectedAt.Format(time.RFC3339), "handlingCompliant": true,
		}
		return out, nil
	}
	if collectedAt.Before(earliest) || collectedAt.After(latest) {
		return nil, Conflict("invalid_sample_state", "outside collection window")
	}
	compliant := temp >= tmin && temp <= tmax
	_, err = s.DB.PG.Exec(ctx, `
		UPDATE samples SET sealed=TRUE, sealed_at=$1, status='sealed', current_holder_id=$2,
			container_type=$3, updated_at=NOW() WHERE id=$4`, collectedAt, sess.UserID, container, sampleID)
	if err != nil {
		return nil, Internal(err.Error())
	}
	_, _ = s.DB.PG.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=$1, updated_at=NOW() WHERE id=$2`, collectedAt, aID)
	if !compliant {
		exc := map[string]interface{}{"reason": "handling_checkpoint_failed", "temperature": temp}
		b := jsonMarshal(exc)
		_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET status='exception', exception=$1 WHERE id=$2`, b, sampleID)
	}
	s.Timeline(ctx, "collected_and_sealed", sess.UserID.String(), sess.ActiveRole, "sample", sampleID.String(), true,
		map[string]interface{}{"compliant": compliant}, &sampleID, nil, &aID)
	out := map[string]interface{}{
		"sampleId": sampleID.String(), "status": "sealed", "currentHolderId": sess.UserID.String(),
		"sealedAt": collectedAt.UTC().Format(time.RFC3339), "handlingCompliant": compliant,
	}
	s.SaveIdempotent(ctx, idem, "collect_and_seal_sample", hashReq(body), &sess.UserID, 201, map[string]interface{}{"data": out})
	return out, nil
}

func (s *Service) InitiateHandoff(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator); err != nil {
		return nil, err
	}
	idem, _ := body["idempotencyKey"].(string)
	if idem == "" {
		return nil, Bad("idempotency_required", "required")
	}
	sampleID, err := parseUUID(body["sampleId"])
	if err != nil {
		return nil, Bad("invalid_json", "sampleId")
	}
	fromA, err := parseUUID(body["fromAssignmentId"])
	if err != nil {
		return nil, Bad("invalid_json", "fromAssignmentId")
	}
	toA, err := parseUUID(body["toAssignmentId"])
	if err != nil {
		return nil, Bad("invalid_json", "toAssignmentId")
	}
	receiverID, err := parseUUID(body["receiverId"])
	if err != nil {
		return nil, Bad("invalid_receiver", "receiverId")
	}
	initiatedAt, err := parseTime(body["initiatedAt"])
	if err != nil {
		return nil, Bad("invalid_time", "initiatedAt")
	}

	var holder *uuid.UUID
	var pending *uuid.UUID
	var sealed bool
	err = s.DB.PG.QueryRow(ctx, `SELECT current_holder_id, pending_handoff_id, sealed FROM samples WHERE id=$1`, sampleID).
		Scan(&holder, &pending, &sealed)
	if err != nil {
		return nil, NotFound("not_found", "sample")
	}
	if !sealed {
		return nil, Conflict("invalid_sample_state", "not sealed")
	}
	if holder == nil || *holder != sess.UserID {
		return nil, Conflict("not_current_holder", "not holder")
	}
	if pending != nil {
		return nil, Conflict("pending_handoff_exists", "pending exists")
	}
	var toWorker *uuid.UUID
	var toStatus string
	err = s.DB.PG.QueryRow(ctx, `SELECT worker_id, status FROM assignments WHERE id=$1 AND sample_id=$2`, toA, sampleID).
		Scan(&toWorker, &toStatus)
	if err != nil {
		return nil, NotFound("not_found", "to assignment")
	}
	if toWorker == nil || *toWorker != receiverID {
		return nil, Conflict("receiver_assignment_mismatch", "receiver mismatch")
	}
	if toStatus != "accepted" && toStatus != "in_progress" {
		return nil, Conflict("invalid_assignment_state", "receiver assignment not ready")
	}

	hID := uuid.New()
	_, err = s.DB.PG.Exec(ctx, `
		INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
		VALUES ($1,$2,$3,$4,$5,$6,'pending',$7)`, hID, sampleID, fromA, toA, sess.UserID, receiverID, initiatedAt)
	if err != nil {
		return nil, Internal(err.Error())
	}
	_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET pending_handoff_id=$1 WHERE id=$2`, hID, sampleID)
	s.Timeline(ctx, "handoff_initiated", sess.UserID.String(), sess.ActiveRole, "handoff", hID.String(), true, nil, &sampleID, nil, &fromA)
	out := map[string]interface{}{
		"handoffId": hID.String(), "senderId": sess.UserID.String(), "receiverId": receiverID.String(),
		"currentHolderId": sess.UserID.String(), "status": "pending",
	}
	return out, nil
}

func (s *Service) ConfirmHandoff(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator); err != nil {
		return nil, err
	}
	idem, _ := body["idempotencyKey"].(string)
	if idem == "" {
		return nil, Bad("idempotency_required", "required")
	}
	hID, err := parseUUID(body["handoffId"])
	if err != nil {
		return nil, Bad("invalid_json", "handoffId")
	}
	side, _ := body["confirmationSide"].(string)
	if side != "sender" && side != "receiver" {
		return nil, Bad("invalid_json", "confirmationSide")
	}
	confirmedAt, err := parseTime(body["confirmedAt"])
	if err != nil {
		return nil, Bad("invalid_time", "confirmedAt")
	}

	var senderID, receiverID, sampleID uuid.UUID
	var senderConf, receiverConf bool
	var status string
	err = s.DB.PG.QueryRow(ctx, `
		SELECT sender_id, receiver_id, sample_id, sender_confirmed, receiver_confirmed, status FROM handoffs WHERE id=$1`, hID).
		Scan(&senderID, &receiverID, &sampleID, &senderConf, &receiverConf, &status)
	if err == pgx.ErrNoRows {
		return nil, NotFound("not_found", "handoff")
	}
	if err != nil {
		return nil, Internal(err.Error())
	}
	if side == "sender" {
		if sess.UserID != senderID && sess.ActiveRole != models.RoleAdministrator {
			return nil, Forbid("forbidden", "not sender")
		}
		senderConf = true
		_, _ = s.DB.PG.Exec(ctx, `UPDATE handoffs SET sender_confirmed=TRUE, sender_confirmed_at=$1 WHERE id=$2`, confirmedAt, hID)
	} else {
		if sess.UserID != receiverID && sess.ActiveRole != models.RoleAdministrator {
			return nil, Forbid("forbidden", "not receiver")
		}
		receiverConf = true
		_, _ = s.DB.PG.Exec(ctx, `UPDATE handoffs SET receiver_confirmed=TRUE, receiver_confirmed_at=$1 WHERE id=$2`, confirmedAt, hID)
	}
	// reload
	_ = s.DB.PG.QueryRow(ctx, `SELECT sender_confirmed, receiver_confirmed FROM handoffs WHERE id=$1`, hID).Scan(&senderConf, &receiverConf)
	holder := senderID
	st := "pending"
	if senderConf && receiverConf {
		st = "confirmed"
		holder = receiverID
		_, _ = s.DB.PG.Exec(ctx, `UPDATE handoffs SET status='confirmed', completed_at=$1 WHERE id=$2`, confirmedAt, hID)
		_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET current_holder_id=$1, pending_handoff_id=NULL, status='in_transit', updated_at=NOW() WHERE id=$2`, receiverID, sampleID)
		// complete from assignment progress-wise if needed
	}
	s.Timeline(ctx, "handoff_confirmed", sess.UserID.String(), sess.ActiveRole, "handoff", hID.String(), true,
		map[string]interface{}{"side": side, "status": st}, &sampleID, nil, nil)
	return map[string]interface{}{
		"handoffId": hID.String(), "status": st, "senderConfirmed": senderConf, "receiverConfirmed": receiverConf,
		"currentHolderId": holder.String(),
	}, nil
}

func (s *Service) UpdateAssignmentProgress(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator, models.RoleDispatcher); err != nil {
		return nil, err
	}
	idem, _ := body["idempotencyKey"].(string)
	if idem == "" {
		return nil, Bad("idempotency_required", "required")
	}
	aID, err := parseUUID(body["assignmentId"])
	if err != nil {
		return nil, Bad("invalid_json", "assignmentId")
	}
	status, _ := body["status"].(string)
	occurredAt, err := parseTime(body["occurredAt"])
	if err != nil {
		return nil, Bad("invalid_time", "occurredAt")
	}
	var aStatus, kind string
	var workerID *uuid.UUID
	var sampleID, journeyID uuid.UUID
	err = s.DB.PG.QueryRow(ctx, `SELECT status, kind, worker_id, sample_id, journey_id FROM assignments WHERE id=$1`, aID).
		Scan(&aStatus, &kind, &workerID, &sampleID, &journeyID)
	if err != nil {
		return nil, NotFound("not_found", "assignment")
	}
	if aStatus != "accepted" && aStatus != "in_progress" && aStatus != "completed" {
		return nil, Conflict("assignment_inactive", "inactive")
	}
	if workerID != nil && *workerID != sess.UserID && sess.ActiveRole != models.RoleAdministrator && sess.ActiveRole != models.RoleDispatcher {
		return nil, Forbid("ineligible_worker", "not assignee")
	}
	newStatus := aStatus
	if status == "completed" || status == "delivered" {
		newStatus = "completed"
		_, _ = s.DB.PG.Exec(ctx, `UPDATE assignments SET status='completed', progress_status=$1, completed_at=$2, updated_at=NOW() WHERE id=$3`, status, occurredAt, aID)
		_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET completed_leg_ids = array_append(completed_leg_ids, $1) WHERE id=$2`, aID, sampleID)
	} else {
		newStatus = "in_progress"
		_, _ = s.DB.PG.Exec(ctx, `UPDATE assignments SET status='in_progress', progress_status=$1, started_at=COALESCE(started_at,$2), updated_at=NOW() WHERE id=$3`, status, occurredAt, aID)
		_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET status='in_transit', updated_at=NOW() WHERE id=$1 AND status NOT IN ('received','exception','cancelled')`, sampleID)
	}
	s.Timeline(ctx, "assignment_progress", sess.UserID.String(), sess.ActiveRole, "assignment", aID.String(), true,
		map[string]interface{}{"status": status}, &sampleID, &journeyID, &aID)
	return map[string]interface{}{"assignmentId": aID.String(), "sampleId": sampleID.String(), "status": statusOrProgress(newStatus, status)}, nil
}

func statusOrProgress(a, p string) string {
	if p != "" {
		return p
	}
	return a
}

