func (s *Service) CancelJourney(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireAdminOrDispatcher(sess); err != nil {
		return nil, err
	}
	jID, err := parseUUID(body["journeyId"])
	if err != nil {
		return nil, Bad("invalid_json", "journeyId")
	}
	expectedVersion := toInt(body["expectedPlanVersion"], 0)
	var version int
	var status string
	err = s.DB.PG.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE id=$1`, jID).Scan(&version, &status)
	if err == pgx.ErrNoRows {
		return nil, NotFound("not_found", "journey not found")
	}
	if err != nil {
		return nil, Internal(err.Error())
	}
	if expectedVersion > 0 && expectedVersion != version {
		return nil, Conflict("plan_version_conflict", "plan version mismatch")
	}
	if status == "completed" {
		return nil, Conflict("completed_work_immutable", "cannot cancel completed journey")
	}
	_, _ = s.DB.PG.Exec(ctx, `UPDATE journeys SET status='cancelled', plan_version=plan_version+1, updated_at=NOW() WHERE id=$1`, jID)
	_, _ = s.DB.PG.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=NOW() WHERE journey_id=$1 AND status NOT IN ('completed')`, jID)
	_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET status='cancelled', updated_at=NOW() WHERE active_journey_id=$1 AND status NOT IN ('received')`, jID)
	s.releaseJourneyCapacity(ctx, jID)
	s.Audit(ctx, sess.UserID.String(), sess.ActiveRole, "cancel_journey", "journey", jID.String(), true, nil)
	return map[string]interface{}{"journeyId": jID.String(), "status": "cancelled", "planVersion": version + 1}, nil
}

func (s *Service) RerouteJourney(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireAdminOrDispatcher(sess); err != nil {
		return nil, err
	}
	jID, err := parseUUID(body["journeyId"])
	if err != nil {
		return nil, Bad("invalid_json", "journeyId")
	}
	expectedVersion := toInt(body["expectedPlanVersion"], 0)
	var version int
	var status string
	var sampleIDs []uuid.UUID
	err = s.DB.PG.QueryRow(ctx, `SELECT plan_version, status, sample_ids FROM journeys WHERE id=$1`, jID).Scan(&version, &status, &sampleIDs)
	if err == pgx.ErrNoRows {
		return nil, NotFound("not_found", "journey")
	}
	if expectedVersion > 0 && expectedVersion != version {
		return nil, Conflict("plan_version_conflict", "version mismatch")
	}
	if status == "completed" || status == "cancelled" {
		return nil, Conflict("completed_work_immutable", "immutable")
	}
	if len(sampleIDs) == 0 {
		return nil, Conflict("no_valid_route", "no samples")
	}
	sampleID := sampleIDs[0]
	// load sample for replan
	var olat, olng float64
	var originType string
	var originNode *uuid.UUID
	var earliest, latest, deadline time.Time
	var stID uuid.UUID
	var sealed bool
	err = s.DB.PG.QueryRow(ctx, `
		SELECT origin_lat, origin_lng, origin_type, origin_node_id, earliest_collection_at, latest_collection_at,
			delivery_deadline, sample_type_id, sealed FROM samples WHERE id=$1`, sampleID).
		Scan(&olat, &olng, &originType, &originNode, &earliest, &latest, &deadline, &stID, &sealed)
	if err != nil {
		return nil, Internal(err.Error())
	}
	st, aerr := s.getSampleType(ctx, stID)
	if aerr != nil {
		return nil, aerr
	}
	svcBody := map[string]interface{}{
		"origin": map[string]interface{}{"latitude": olat, "longitude": olng},
		"originType": originType, "sampleTypeId": stID.String(),
		"requestedAt": time.Now().UTC().Format(time.RFC3339),
		"deliveryDeadline": deadline.Format(time.RFC3339),
		"earliestCollectionAt": earliest.Format(time.RFC3339),
		"latestCollectionAt": latest.Format(time.RFC3339),
	}
	if originNode != nil {
		svcBody["originNodeId"] = originNode.String()
	}
	svc, aerr := s.computeServiceability(ctx, svcBody)
	if aerr != nil {
		return nil, aerr
	}
	if !svc.Serviceable {
		_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET status='expired', exception=$1 WHERE id=$2`,
			jsonMarshal(map[string]interface{}{"reason": "deadline_unreachable"}), sampleID)
		return nil, Conflict("deadline_unsatisfiable", "cannot meet deadline")
	}
	// cancel unfinished assignments only
	_, _ = s.DB.PG.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed')`, jID)
	s.releaseJourneyCapacity(ctx, jID)

	tx, err := s.DB.PG.Begin(ctx)
	if err != nil {
		return nil, Internal(err.Error())
	}
	defer tx.Rollback(ctx)

	newJID, assignIDs, e := s.planJourneyTx(ctx, tx, sampleID, models.Coordinate{Latitude: olat, Longitude: olng},
		originType, originNode, earliest, latest, deadline, st, svc, sealed, sess.UserID)
	if e != nil {
		return nil, e
	}
	_, err = tx.Exec(ctx, `UPDATE journeys SET status='superseded', plan_version=$1, updated_at=NOW() WHERE id=$2`, version+1, jID)
	if err != nil {
		return nil, Internal(err.Error())
	}
	_, err = tx.Exec(ctx, `UPDATE journeys SET parent_journey_id=$1 WHERE id=$2`, jID, newJID)
	if err != nil {
		return nil, Internal(err.Error())
	}
	_, err = tx.Exec(ctx, `UPDATE samples SET active_journey_id=$1, target_laboratory_id=$2, updated_at=NOW() WHERE id=$3`,
		newJID, svc.TargetLaboratoryID, sampleID)
	if err != nil {
		return nil, Internal(err.Error())
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, Internal(err.Error())
	}
	aids := make([]string, 0, len(assignIDs))
	for _, a := range assignIDs {
		aids = append(aids, a.String())
	}
	s.Audit(ctx, sess.UserID.String(), sess.ActiveRole, "reroute_journey", "journey", newJID.String(), true, map[string]interface{}{"parent": jID.String()})
	return map[string]interface{}{
		"journeyId": newJID.String(), "parentJourneyId": jID.String(), "planVersion": 1,
		"activeAssignmentIds": aids, "status": "planned",
	}, nil
}

func (s *Service) EditActivePlan(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireAdminOrDispatcher(sess); err != nil {
		return nil, err
	}
	jID, err := parseUUID(body["journeyId"])
	if err != nil {
		return nil, Bad("invalid_json", "journeyId")
	}
	expectedVersion := toInt(body["expectedPlanVersion"], 0)
	var version int
	err = s.DB.PG.QueryRow(ctx, `SELECT plan_version FROM journeys WHERE id=$1`, jID).Scan(&version)
	if err != nil {
		return nil, NotFound("not_found", "journey")
	}
	if expectedVersion > 0 && expectedVersion != version {
		return nil, Conflict("plan_version_conflict", "version mismatch")
	}
	_, _ = s.DB.PG.Exec(ctx, `UPDATE journeys SET plan_version=plan_version+1, updated_at=NOW() WHERE id=$1`, jID)
	s.Audit(ctx, sess.UserID.String(), sess.ActiveRole, "edit_active_plan", "journey", jID.String(), true, nil)
