func (s *Service) SplitJourney(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireAdminOrDispatcher(sess); err != nil {
		return nil, err
	}
	jID, err := parseUUID(body["journeyId"])
	if err != nil {
		return nil, Bad("invalid_json", "journeyId")
	}
	sampleIDs := toUUIDSlice(body["sampleIds"])
	if len(sampleIDs) == 0 {
		return nil, Bad("invalid_json", "sampleIds required")
	}
	var version int
	var all []uuid.UUID
	var status string
	err = s.DB.PG.QueryRow(ctx, `SELECT plan_version, sample_ids, status FROM journeys WHERE id=$1`, jID).Scan(&version, &all, &status)
	if err != nil {
		return nil, NotFound("not_found", "journey")
	}
	if status == "completed" {
		return nil, Conflict("completed_work_immutable", "immutable")
	}
	// create new journey for split samples
	newJID := uuid.New()
	_, err = s.DB.PG.Exec(ctx, `
		INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, sample_ids, valid)
		VALUES ($1,$2,1,'direct','planned',$3,TRUE)`, newJID, jID, sampleIDs)
	if err != nil {
		return nil, Internal(err.Error())
	}
	remain := []uuid.UUID{}
	splitSet := map[uuid.UUID]bool{}
	for _, x := range sampleIDs {
		splitSet[x] = true
		_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET active_journey_id=$1 WHERE id=$2`, newJID, x)
	}
	for _, x := range all {
		if !splitSet[x] {
			remain = append(remain, x)
		}
	}
	_, _ = s.DB.PG.Exec(ctx, `UPDATE journeys SET sample_ids=$1, plan_version=plan_version+1 WHERE id=$2`, remain, jID)
	return map[string]interface{}{
		"originalJourneyId": jID.String(), "newJourneyId": newJID.String(),
		"planVersion": version + 1,
	}, nil
}

func (s *Service) MergeJourneys(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireAdminOrDispatcher(sess); err != nil {
		return nil, err
	}
	ids := toUUIDSlice(body["journeyIds"])
	if len(ids) < 2 {
		return nil, Bad("invalid_json", "need at least 2 journeys")
	}
	// validate compatibility of samples
	allSamples := []uuid.UUID{}
	for _, jid := range ids {
		var sids []uuid.UUID
		var status string
		err := s.DB.PG.QueryRow(ctx, `SELECT sample_ids, status FROM journeys WHERE id=$1`, jid).Scan(&sids, &status)
		if err != nil {
			return nil, NotFound("not_found", "journey")
		}
		if status == "completed" || status == "cancelled" {
			return nil, Conflict("completed_work_immutable", "immutable")
		}
		allSamples = append(allSamples, sids...)
	}
	// check incompatibilities among sample types
	typeIDs := []uuid.UUID{}
	for _, sid := range allSamples {
		var stID uuid.UUID
		_ = s.DB.PG.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE id=$1`, sid).Scan(&stID)
		typeIDs = append(typeIDs, stID)
	}
	for _, tid := range typeIDs {
		st, aerr := s.getSampleType(ctx, tid)
		if aerr != nil {
			continue
		}
		if !st.BatchingAllowed {
			return nil, Conflict("batching_not_allowed", "sample type does not allow batching")
		}
		for _, other := range typeIDs {
			if containsUUID(st.IncompatibleSampleTypes, other) {
				return nil, Conflict("incompatible_samples", "incompatible sample types")
			}
		}
	}
	target := ids[0]
	merged := []uuid.UUID{}
	for _, jid := range ids {
		var sids []uuid.UUID
		_ = s.DB.PG.QueryRow(ctx, `SELECT sample_ids FROM journeys WHERE id=$1`, jid).Scan(&sids)
		merged = append(merged, sids...)
		if jid != target {
			_, _ = s.DB.PG.Exec(ctx, `UPDATE journeys SET status='merged', updated_at=NOW() WHERE id=$1`, jid)
			for _, sid := range sids {
				_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET active_journey_id=$1 WHERE id=$2`, target, sid)
			}
		}
	}
	_, _ = s.DB.PG.Exec(ctx, `UPDATE journeys SET sample_ids=$1, route_mode='batched', plan_version=plan_version+1, updated_at=NOW() WHERE id=$2`, merged, target)
	var version int
	_ = s.DB.PG.QueryRow(ctx, `SELECT plan_version FROM journeys WHERE id=$1`, target).Scan(&version)
	return map[string]interface{}{"journeyId": target.String(), "sampleIds": uuidStrings(merged), "planVersion": version}, nil
}

func uuidStrings(ids []uuid.UUID) []string {
	out := make([]string, len(ids))
	for i, id := range ids {
		out[i] = id.String()
	}
	return out
}

func (s *Service) ReportDisruption(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireAdminOrDispatcher(sess); err != nil {
		return nil, err
	}
	resourceType, _ := body["resourceType"].(string)
	resourceID, _ := body["resourceId"].(string)
	if resourceType == "" || resourceID == "" {
		return nil, Bad("invalid_json", "resourceType and resourceId required")
	}
	reason, _ := body["reason"].(string)
	occurredAt := time.Now().UTC()
	if v, ok := body["occurredAt"].(string); ok && v != "" {
		if t, e := parseTime(v); e == nil {
			occurredAt = t
		}
	}
	// deactivate resource
	switch resourceType {
	case "location", "node", "laboratory":
		if id, e := uuid.Parse(resourceID); e == nil {
			_, _ = s.DB.PG.Exec(ctx, `UPDATE locations SET active=FALSE, updated_at=NOW() WHERE id=$1`, id)
		}
	case "connection", "route":
		if id, e := uuid.Parse(resourceID); e == nil {
			_, _ = s.DB.PG.Exec(ctx, `UPDATE connections SET active=FALSE, updated_at=NOW() WHERE id=$1`, id)
		}
	case "worker":
		if id, e := uuid.Parse(resourceID); e == nil {
			_, _ = s.DB.PG.Exec(ctx, `UPDATE users SET available=FALSE WHERE id=$1`, id)
		}
	}
	s.bumpNetwork(ctx)

	// find affected unfinished samples
	affected := []uuid.UUID{}
	rows, err := s.DB.PG.Query(ctx, `
		SELECT DISTINCT s.id, s.active_journey_id FROM samples s
		WHERE s.status NOT IN ('received','cancelled','expired') AND s.active_journey_id IS NOT NULL`)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var sid uuid.UUID
			var jid *uuid.UUID
			if rows.Scan(&sid, &jid) != nil {
				continue
			}
			affected = append(affected, sid)
		}
	}

	replacementIDs := []uuid.UUID{}
	replanStatus := "not_required"
	if len(affected) > 0 {
		replanStatus = "replanned"
		for _, sid := range affected {
			var jid *uuid.UUID
			_ = s.DB.PG.QueryRow(ctx, `SELECT active_journey_id FROM samples WHERE id=$1`, sid).Scan(&jid)
			if jid == nil {
				continue
			}
			// only one active replacement
			res, aerr := s.RerouteJourney(ctx, sess, map[string]interface{}{
				"journeyId": jid.String(), "expectedPlanVersion": 0,
			})
			if aerr != nil {
				// mark expired if cannot replan
				if aerr.Code == "deadline_unsatisfiable" {
					continue
				}
				replanStatus = "partial"
				continue
			}
			if nj, ok := res["journeyId"].(string); ok {
				if id, e := uuid.Parse(nj); e == nil {
					replacementIDs = append(replacementIDs, id)
					_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET active_replacement_plan_ids=$1 WHERE id=$2`, []uuid.UUID{id}, sid)
				}
			}
		}
	}

	dID := uuid.New()
	_, _ = s.DB.PG.Exec(ctx, `
		INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, dID, resourceType, resourceID, reason, occurredAt, affected, replacementIDs, replanStatus)
	s.Audit(ctx, sess.UserID.String(), sess.ActiveRole, "report_disruption", resourceType, resourceID, true, map[string]interface{}{"disruptionId": dID.String()})
	return map[string]interface{}{
		"disruptionId": dID.String(),
		"affectedSampleIds": uuidStrings(affected),
		"replacementPlanIds": uuidStrings(replacementIDs),
		"replanStatus": replanStatus,
	}, nil
}

// Expire stale offers periodically
func (s *Service) ProcessExpiredOffers(ctx context.Context) {
	rows, err := s.DB.PG.Query(ctx, `
		SELECT id, sample_id, kind, node_id, laboratory_id, offered_to, declined_by
		FROM assignments WHERE status='offered' AND offer_expires_at < NOW()`)
	if err != nil {
		return
	}
	defer rows.Close()
	type item struct {
		id, sampleID uuid.UUID
		kind         string
		node, lab, offered *uuid.UUID
		declined     []uuid.UUID
	}
	var list []item
	for rows.Next() {
		var it item
		if rows.Scan(&it.id, &it.sampleID, &it.kind, &it.node, &it.lab, &it.offered, &it.declined) == nil {
			list = append(list, it)
		}
	}
	for _, it := range list {
		declined := it.declined
		if it.offered != nil {
			declined = append(declined, *it.offered)
		}
		_, _ = s.DB.PG.Exec(ctx, `
			UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL,
				declined_by=$1, updated_at=NOW() WHERE id=$2`, declined, it.id)
		st, _ := s.getSampleTypeBySample(ctx, it.sampleID)
		var loc *uuid.UUID
		if it.kind == "node" {
			loc = it.node
		} else if it.kind == "laboratory" {
			loc = it.lab
		}
		s.reoffer(ctx, it.id, it.kind, it.sampleID, st, loc, declined)
		// if still no offer after reoffer and collection, flag exception
		var status string
		var offered *uuid.UUID
		_ = s.DB.PG.QueryRow(ctx, `SELECT status, offered_to FROM assignments WHERE id=$1`, it.id).Scan(&status, &offered)
		if status == "pending" && offered == nil && it.kind == "collection" {
			exc := map[string]interface{}{"reason": "no_qualified_worker_available"}
			_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET status='exception', exception=$1 WHERE id=$2 AND status NOT IN ('received','cancelled')`,
				jsonMarshal(exc), it.sampleID)
		}
	}
}
"}

