{"path":"/workspace/backend/cmd/server/main.go","command":"create","file_text":"package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"
	"time"

	"labpd/internal/api"
	"labpd/internal/auth"
	"labpd/internal/db"
	"labpd/internal/service"
)

func main() {
	ctx := context.Background()
	database, err := db.Connect(ctx)
	if err != nil {
		log.Fatalf("db connect: %v", err)
	}
	defer database.Close()

	authSvc := auth.New(database)
	svc := service.New(database, authSvc)
	if err := svc.EnsureBootstrap(ctx); err != nil {
		log.Fatalf("bootstrap: %v", err)
	}
	if err := svc.EnsureMongoIndexes(ctx); err != nil {
		log.Printf("mongo indexes: %v", err)
	}

	staticDir := os.Getenv("STATIC_DIR")
	if staticDir == "" {
		staticDir = "/workspace/frontend/dist"
	}
	mapDir := os.Getenv("MAP_DIR")
	if mapDir == "" {
		mapDir = "/opt/arena/map-assets"
		if _, err := os.Stat(mapDir); err != nil {
			mapDir = filepath.Join(staticDir, "map")
		}
	}

	srv := api.New(svc, authSvc, staticDir, mapDir)
	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}

	httpServer := &http.Server{
		Addr:              addr,
		Handler:           withCORS(srv.Router),
		ReadHeaderTimeout: 10 * time.Second,
	}

	// background offer expiry
	go func() {
		t := time.NewTicker(30 * time.Second)
		defer t.Stop()
		for range t.C {
			svc.ProcessExpiredOffers(context.Background())
		}
	}()

	go func() {
		log.Printf("listening on %s", addr)
		if err := httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("listen: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = httpServer.Shutdown(shutdownCtx)
}

func withCORS(h http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		h.ServeHTTP(w, r)
	})
}
"}

