{"path":"/workspace/frontend/src/api.ts","command":"create","file_text":"export type Role =
  | 'requester'
  | 'collection_professional'
  | 'delivery_partner'
  | 'node_handler'
  | 'laboratory_team'
  | 'dispatcher'
  | 'administrator'

export interface AuthSession {
  token: string
  userId: string
  username: string
  displayName: string
  roles: Role[]
  activeRole: Role
  assignedLocationIds: string[]
  certifications: string[]
}

const TOKEN_KEY = 'labpd_token'
const SESSION_KEY = 'labpd_session'

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY)
}

export function getSession(): AuthSession | null {
  const raw = localStorage.getItem(SESSION_KEY)
  if (!raw) return null
  try { return JSON.parse(raw) } catch { return null }
}

export function saveSession(s: AuthSession) {
  localStorage.setItem(TOKEN_KEY, s.token)
  localStorage.setItem(SESSION_KEY, JSON.stringify(s))
}

export function clearSession() {
  localStorage.removeItem(TOKEN_KEY)
  localStorage.removeItem(SESSION_KEY)
}

export class ApiError extends Error {
  code: string
  status: number
  constructor(status: number, code: string, message: string) {
    super(message)
    this.status = status
    this.code = code
  }
}

export async function api<T = any>(
  path: string,
  opts: { method?: string; body?: any; auth?: boolean } = {}
): Promise<T> {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' }
  if (opts.auth !== false) {
    const token = getToken()
    if (token) headers.Authorization = `Bearer ${token}`
  }
  const res = await fetch(`/api${path}`, {
    method: opts.method || (opts.body ? 'POST' : 'GET'),
    headers,
    body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
  })
  const text = await res.text()
  let json: any = null
  try { json = text ? JSON.parse(text) : null } catch { json = { error: text } }
  if (!res.ok) {
    throw new ApiError(res.status, json?.code || 'error', json?.error || res.statusText)
  }
  return (json?.data !== undefined ? json.data : json) as T
}

export function uuid(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID()
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0
    const v = c === 'x' ? r : (r & 0x3 | 0x8)
    return v.toString(16)
  })
}

export function roleLabel(r: string): string {
  return r.replace(/_/g, ' ')
}
"}

