{"path":"/workspace/frontend/src/pages/WorkPage.tsx","command":"create","file_text":"import { useEffect, useState } from 'react'
import { api, AuthSession, uuid } from '../api'

export default function WorkPage({ session }: { session: AuthSession; bootstrap?: any }) {
  const [scope, setScope] = useState<'current' | 'past'>('current')
  const [items, setItems] = useState<any[]>([])
  const [error, setError] = useState('')
  const [msg, setMsg] = useState('')
  const [busy, setBusy] = useState<string | null>(null)
  const [location, setLocation] = useState({ latitude: 12.9716, longitude: 77.5946 })

  async function load() {
    setError('')
    try {
      const data = await api<any>('/list-role-work', {
        body: { scope, role: session.activeRole },
      })
      setItems(data.items || data.workItems || data || [])
    } catch (e: any) {
      setError(e.message)
    }
  }

  useEffect(() => { load() }, [scope, session.activeRole])

  async function accept(assignmentId: string) {
    setBusy(assignmentId)
    setMsg('')
    try {
      await api('/accept-assignment', {
        body: { assignmentId, idempotencyKey: uuid() },
      })
      setMsg('Assignment accepted')
      await load()
    } catch (e: any) {
      setError(e.message)
    } finally {
      setBusy(null)
    }
  }

  async function decline(assignmentId: string) {
    setBusy(assignmentId)
    try {
      await api('/decline-assignment', {
        body: { assignmentId, reason: 'unavailable', idempotencyKey: uuid() },
      })
      setMsg('Assignment declined')
      await load()
    } catch (e: any) {
      setError(e.message)
    } finally {
      setBusy(null)
    }
  }

  async function collect(assignmentId: string, sampleId: string) {
    setBusy(assignmentId)
    try {
      await api('/collect-and-seal-sample', {
        body: {
          assignmentId,
          sampleId,
          sealedAt: new Date().toISOString(),
          containerType: 'standard',
          observedTemperatureC: 4,
          location,
          idempotencyKey: uuid(),
        },
      })
      setMsg('Sample collected and sealed')
      await load()
    } catch (e: any) {
      setError(e.message)
    } finally {
      setBusy(null)
    }
  }

  async function confirmReceipt(assignmentId: string, sampleId: string) {
    setBusy(assignmentId)
    try {
      await api('/confirm-laboratory-receipt', {
        body: {
          assignmentId,
          sampleId,
          receivedAt: new Date().toISOString(),
          condition: 'accepted',
          idempotencyKey: uuid(),
        },
      })
      setMsg('Laboratory receipt confirmed')
      await load()
    } catch (e: any) {
      setError(e.message)
    } finally {
      setBusy(null)
    }
  }

  async function updateLoc() {
    try {
      await api('/record-worker-location', {
        body: {
          workerId: session.userId,
          location,
          recordedAt: new Date().toISOString(),
          idempotencyKey: uuid(),
        },
      })
      setMsg('Location updated')
    } catch (e: any) {
      setError(e.message)
    }
  }

  return (
    <div className="grid">
      <div className="card">
        <div className="tabs">
          <button className={`tab ${scope === 'current' ? 'active' : ''}`} onClick={() => setScope('current')}>Current</button>
          <button className={`tab ${scope === 'past' ? 'active' : ''}`} onClick={() => setScope('past')}>Past</button>
          <button className="secondary" onClick={load}>Refresh</button>
        </div>
        <div className="row">
          <div className="field">
            <label>My latitude</label>
            <input type="number" step="0.0001" value={location.latitude}
              onChange={e => setLocation(l => ({ ...l, latitude: Number(e.target.value) }))} />
          </div>
          <div className="field">
            <label>My longitude</label>
            <input type="number" step="0.0001" value={location.longitude}
              onChange={e => setLocation(l => ({ ...l, longitude: Number(e.target.value) }))} />
          </div>
          <div className="field" style={{ display: 'flex', alignItems: 'end' }}>
            <button className="secondary" onClick={updateLoc}>Update location</button>
          </div>
        </div>
        {error && <div className="error-box">{error}</div>}
        {msg && <div className="success-box">{msg}</div>}
      </div>

      <div className="card">
        <table className="table">
          <thead>
            <tr>
              <th>Kind</th>
              <th>Status</th>
              <th>Sample</th>
              <th>Details</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.length === 0 && (
              <tr><td colSpan={5} className="muted">No work items</td></tr>
            )}
            {items.map((it, idx) => {
              const id = it.assignmentId || it.id
              const sampleId = it.sampleId
              return (
                <tr key={id || idx}>
                  <td><span className="badge">{it.kind || it.type || 'work'}</span></td>
                  <td>{it.status}</td>
                  <td className="muted" style={{ fontSize: '0.8rem' }}>{sampleId}</td>
                  <td className="muted">
                    {it.fromLocationName || it.originLabel || ''}
                    {it.toLocationName ? ` → ${it.toLocationName}` : ''}
                    {it.offerExpiresAt ? ` · offer until ${it.offerExpiresAt}` : ''}
                  </td>
                  <td>
                    <div className="row" style={{ minWidth: 220 }}>
                      {it.status === 'offered' && (
                        <>
                          <button disabled={busy === id} onClick={() => accept(id)}>Accept</button>
                          <button className="secondary" disabled={busy === id} onClick={() => decline(id)}>Decline</button>
                        </>
                      )}
                      {it.kind === 'collection' && ['accepted', 'in_progress'].includes(it.status) && (
                        <button disabled={busy === id} onClick={() => collect(id, sampleId)}>Collect & seal</button>
                      )}
                      {it.kind === 'laboratory' && ['accepted', 'in_progress'].includes(it.status) && (
                        <button disabled={busy === id} onClick={() => confirmReceipt(id, sampleId)}>Confirm receipt</button>
                      )}
                    </div>
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>
    </div>
  )
}
"}

{"path":"/workspace/frontend/src/pages/RequestPage.tsx","command":"create","file_text":"import { useEffect, useState } from 'react'
import { api, AuthSession, uuid } from '../api'

function isoPlusHours(h: number) {
  return new Date(Date.now() + h * 3600_000).toISOString()
}

export default function RequestPage({ session, bootstrap }: { session: AuthSession; bootstrap?: any }) {
  const sampleTypes = bootstrap?.sampleTypes || []
  const [form, setForm] = useState({
    originType: 'home',
    latitude: 12.9716,
    longitude: 77.5946,
    sampleTypeId: '',
    earliestCollectionAt: isoPlusHours(1),
    latestCollectionAt: isoPlusHours(4),
    deliveryDeadline: isoPlusHours(12),
  })
  const [svc, setSvc] = useState<any>(null)
  const [created, setCreated] = useState<any>(null)
  const [items, setItems] = useState<any[]>([])
  const [error, setError] = useState('')
  const [msg, setMsg] = useState('')

  useEffect(() => {
    if (sampleTypes.length && !form.sampleTypeId) {
      setForm(f => ({ ...f, sampleTypeId: sampleTypes[0].id }))
    }
  }, [sampleTypes])

  async function loadMine() {
    try {
      const data = await api<any>('/list-role-work', {
        body: { scope: 'current', role: 'requester' },
      })
      setItems(data.items || data.workItems || data.requests || [])
    } catch {
      /* requester may only see requests via ops if dispatcher */
    }
  }

  useEffect(() => { loadMine() }, [session.activeRole])

  async function checkServiceability() {
    setError('')
    setSvc(null)
    try {
      const data = await api('/check-serviceability', {
        body: {
          origin: { latitude: form.latitude, longitude: form.longitude },
          originType: form.originType,
          sampleTypeId: form.sampleTypeId,
          requestedAt: new Date().toISOString(),
          earliestCollectionAt: form.earliestCollectionAt,
          latestCollectionAt: form.latestCollectionAt,
          deliveryDeadline: form.deliveryDeadline,
        },
      })
      setSvc(data)
      setMsg(data.serviceable ? 'Serviceable' : `Not serviceable: ${data.reason || data.reasons}`)
    } catch (e: any) {
      setError(e.message)
    }
  }

  async function createRequest() {
    setError('')
    setCreated(null)
    try {
      const data = await api('/create-collection-request', {
        body: {
          origin: { latitude: form.latitude, longitude: form.longitude },
          originType: form.originType,
          sampleTypeId: form.sampleTypeId,
          earliestCollectionAt: form.earliestCollectionAt,
          latestCollectionAt: form.latestCollectionAt,
          deliveryDeadline: form.deliveryDeadline,
          idempotencyKey: uuid(),
        },
      })
      setCreated(data)
      setMsg('Collection request created')
      await loadMine()
    } catch (e: any) {
      setError(e.message)
    }
  }

  return (
    <div className="grid" style={{ gridTemplateColumns: '1fr 1fr' }}>
      <div className="card">
        <h3 style={{ marginTop: 0 }}>Serviceability & request</h3>
        {error && <div className="error-box">{error}</div>}
        {msg && <div className="success-box">{msg}</div>}
        <div className="field">
          <label>Origin type</label>
          <select value={form.originType} onChange={e => setForm(f => ({ ...f, originType: e.target.value }))}>
            <option value="home">Home</option>
            <option value="clinic">Clinic</option>
            <option value="node">Network node</option>
          </select>
        </div>
        <div className="row">
          <div className="field">
            <label>Latitude</label>
            <input type="number" step="0.0001" value={form.latitude}
              onChange={e => setForm(f => ({ ...f, latitude: Number(e.target.value) }))} />
          </div>
          <div className="field">
            <label>Longitude</label>
            <input type="number" step="0.0001" value={form.longitude}
              onChange={e => setForm(f => ({ ...f, longitude: Number(e.target.value) }))} />
          </div>
        </div>
        <div className="field">
          <label>Sample type</label>
          <select value={form.sampleTypeId} onChange={e => setForm(f => ({ ...f, sampleTypeId: e.target.value }))}>
            {sampleTypes.map((st: any) => (
              <option key={st.id} value={st.id}>{st.name}</option>
            ))}
          </select>
        </div>
        <div className="field">
          <label>Earliest collection</label>
          <input type="datetime-local"
            value={form.earliestCollectionAt.slice(0, 16)}
            onChange={e => setForm(f => ({ ...f, earliestCollectionAt: new Date(e.target.value).toISOString() }))} />
        </div>
        <div className="field">
          <label>Latest collection</label>
          <input type="datetime-local"
            value={form.latestCollectionAt.slice(0, 16)}
            onChange={e => setForm(f => ({ ...f, latestCollectionAt: new Date(e.target.value).toISOString() }))} />
        </div>
        <div className="field">
          <label>Delivery deadline</label>
          <input type="datetime-local"
            value={form.deliveryDeadline.slice(0, 16)}
            onChange={e => setForm(f => ({ ...f, deliveryDeadline: new Date(e.target.value).toISOString() }))} />
        </div>
        <div className="row">
          <button className="secondary" onClick={checkServiceability}>Check serviceability</button>
          <button onClick={createRequest}>Create request</button>
        </div>
        {svc && <pre className="json">{JSON.stringify(svc, null, 2)}</pre>}
        {created && <pre className="json">{JSON.stringify(created, null, 2)}</pre>}
      </div>
      <div className="card">
        <h3 style={{ marginTop: 0 }}>My requests / work</h3>
        <table className="table">
          <thead>
            <tr><th>ID</th><th>Status</th><th>Type</th></tr>
          </thead>
          <tbody>
            {items.length === 0 && <tr><td colSpan={3} className="muted">No items</td></tr>}
            {items.map((it: any, i: number) => (
              <tr key={it.requestId || it.sampleId || i}>
                <td className="muted" style={{ fontSize: '0.8rem' }}>{it.requestId || it.sampleId || it.id}</td>
                <td>{it.status}</td>
                <td>{it.sampleTypeName || it.kind || '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}
"}

{"path":"/workspace/frontend/src/pages/OpsPage.tsx","command":"create","file_text":"import { useEffect, useState } from 'react'
import { api, AuthSession, uuid } from '../api'

export default function OpsPage({ session }: { session: AuthSession; bootstrap?: any }) {
  const [state, setState] = useState<any>(null)
