    try {
      await api("/collect-and-seal-sample", {
        body: {
          assignmentId,
          sampleId,
          collectedAt: new Date().toISOString(),
          containerType: "standard",
          observedTemperatureC: 4,
          idempotencyKey: uuid(),
        },
      })
      setMsg("Sample collected and sealed")
      await load()
    } catch (e: any) {
      setError(e.message)
    } finally {
      setBusy(null)
    }
  }

  async function confirmReceipt(sampleId: string) {
    setBusy(sampleId)
    try {
      await api("/confirm-laboratory-receipt", {
        body: {
          sampleId,
          laboratoryId: labId,
          receivedAt: new Date().toISOString(),
          idempotencyKey: uuid(),
        },
      })
      setMsg("Laboratory receipt confirmed")
      await load()
    } catch (e: any) {
      setError(e.message)
    } finally {
      setBusy(null)
    }
  }

  async function updateLoc(assignmentId?: string) {
